namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int MaxRatePoints = 10;

    public static int PayableTotalCents(int subtotalCents, LoyaltyTier tier)
    {
        var rate = Math.Min(BaseRatePoints(tier) + BandBonusPoints(subtotalCents), MaxRatePoints);
        var discountCents = (int)((long)subtotalCents * rate / 100);
        return subtotalCents - discountCents;
    }

    private static int BaseRatePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Green => 5,
        LoyaltyTier.Gold => 7,
        LoyaltyTier.Platinum => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier)),
    };

    private static int BandBonusPoints(int subtotalCents) => subtotalCents switch
    {
        >= 20_000 => 3,
        >= 5_000 => 1,
        _ => 0,
    };
}
E
